        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 2, 'mean': 20.0, 'max': 60, 'ratio': 1.0})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 0, 'mean': 0.0, 'max': 0, 'ratio': 0.0})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 2, 'mean': 180.0, 'max': 240, 'ratio': 1.0})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 1, 'mean': 0.0, 'max': 0, 'ratio': 0.5})
